            {
                productClass = "T";
            }
            else
            {
                productClass = "O";
            }
            string externalCounties = "";
            string externalCountiesContinuation = "";
            List<string> lstImpactedCountiesStripped = new List<string>();
            lstImpactedCounties = new List<string>();
            bool flagForUnauthorizedCounty = false;
            bool flagForNewCountyInContinuation = false;
            string cancelledCountiesView2 = "";
