            List<string> oldCounties = new List<string>();
            List<string> newCounties = new List<string>();
            List<string> portionsHit = new List<string>();
            List<string> portionsHit2 = new List<string>();
            List<string> rawCountyNameAffected = new List<string>();
            List<string> rawCountyNameAffected2 = new List<string>();
            List<string> filteredFipsCodes = new List<string>();
            List<string> portionsHit3 = new List<string>();
            List<string> portionsHit4 = new List<string>();
            List<string> portionsHit5 = new List<string>();
            timeZonesInAlert.Clear();
            foreach (string fips in countiesAffectedList)
            {
                // MessageBox.Show($"{ countyData[fips].countyName} {countyData[fips].stateName} {countyData[fips].officeId}");
                if (countyData[fips].officeId == officeId)
                {
                    // MessageBox.Show("Part of CWA");
                    filteredFipsCodes.Add(fips);
                    lstImpactedCountiesStripped.Add($"{countyData[fips].countyName}");
                    if (countyData[fips].countyArea != "")
                    {
                        lstImpactedCounties.Add($"{countyData[fips].countyName} County in {countyLocationMapping[countyData[fips].countyArea]} {stateMappingNames[countyData[fips].stateName]}");
                    }
                    else
                    {
                        lstImpactedCounties.Add($"{countyData[fips].countyName} County in {stateMappingNames[countyData[fips].stateName]}");
                    }
                    rawCountyNameAffected.Add($"{countyData[fips].countyName}");
                    if (portionsHit.Contains($"{fips.Substring(0, 2)}{countyLocationMapping[countyData[fips].countyArea]}"))
                    {

                    }
                    else
                    {
                        portionsHit.Add($"{fips.Substring(0, 2)}{countyLocationMapping[countyData[fips].countyArea]}");
                    }
                    if (portionsHit3.Contains($"{fips.Substring(0, 2)}{countyData[fips].countyArea}"))
                    {

                    }
                    else
                    {
                        portionsHit3.Add($"{fips.Substring(0, 2)}{countyData[fips].countyArea}");
                    }
                    // MessageBox.Show($"county area: {countyData[fips].countyArea}");
                    if (portionsHit5.Contains($"{fips.Substring(0, 2)}{countyData[fips].countyArea}"))
                    {

                    }
                    else
                    {
                        portionsHit5.Add($"{fips.Substring(0, 2)}{countyData[fips].countyArea}");
                    }
                    if (timeZonesInAlert.Contains(countyData[fips].timeZone))
                    {

                    }
                    else
                    {
                        timeZonesInAlert.Add(countyData[fips].timeZone);
                    }
                    countiesAffected += $"{fips}-";
                }
                else
                {
                   // MessageBox.Show("Not CWA");
                    flagForUnauthorizedCounty = true;
                    externalCounties += $"{countyData[fips].countyName} {countyData[fips].stateName} - ";
                }
            }
            portionsHit.Sort();
            portionsHit3.Sort();
            string currentStateProcess = "";
            string portionsListing = "";
            int segmentsWithCurrentState = 0;
            for (int i = 0; i < portionsHit.Count; i++)
            {
                if (currentStateProcess != portionsHit[i].Substring(0, 2))
                {
                    if (currentStateProcess != "")
                    {
                        if (segmentsWithCurrentState > 1)
                        {
                            portionsListing += $"and ";
                        }
                    }
                    if (portionsHit[i].Substring(2) != "")
                    {
                        portionsListing += $"{portionsHit[i].Substring(2)}";
                    }
                    if (currentStateProcess != "")
                    {
                        portionsListing += $" {stateMappingNames[stateMapping[currentStateProcess]]}, ";
                    }
                    else
                    {
                        if (portionsHit.Count != 1)
                        {
                            portionsListing += $", ";
                        }
                    }
                    segmentsWithCurrentState = 0;
                    currentStateProcess = portionsHit[i].Substring(0, 2);
                }
                else
                {
                    if (i == (portionsHit.Count - 1) && portionsHit.Count != 1)
                    {
                        portionsListing += $"and ";
                    }
                    if (portionsHit[i].Substring(2) != "")
                    {
                        portionsListing += $"{portionsHit[i].Substring(2)}";
                    }
                    if (i != (portionsHit.Count - 1))
                    {
                        portionsListing += $", ";
                    }
                }
                segmentsWithCurrentState += 1;
            }
            try
            {
                portionsListing += $" {stateMappingNames[stateMapping[currentStateProcess]]}";
            }
            catch
            {

            }
            portionsListing = "";
            try
            {
                portionsHit5.Sort();
                // MessageBox.Show(portionsHit5[0]);
                string stateThing = portionsHit5[0].Substring(0, 2);
                List<string> countyStorage = new List<string>();
                for (int i = 0; i < portionsHit5.Count; i++)
                {
                    if (portionsHit5[i].Substring(0, 2) == stateThing)
                    {
                        countyStorage.Add(portionsHit5[i].Substring(2));
                    }
                    else
                    {
                        if (countyStorage.Count == 1)
                        {
                            if (portionsListing != "")
                            {
                                portionsListing += ", ";
                            }
                            portionsListing += $"{countyLocationMapping[countyStorage[0]]} {stateMappingNames[stateMapping[stateThing]]}";
                        }
                        else if (countyStorage.Count == 2)
                        {
                            if (portionsListing != "")
                            {
                                portionsListing += ", ";
                            }
                            portionsListing += $"{countyLocationMapping[countyStorage[0]]} and {countyLocationMapping[countyStorage[1]]} {stateMappingNames[stateMapping[stateThing]]}";
                        }
                        else
                        {
                            string lastOne = countyLocationMapping[countyStorage[countyStorage.Count - 1]];
                            countyStorage.RemoveAt(countyStorage.Count - 1);
                            for (int b = 0; b < countyStorage.Count; b++)
                            {
                                countyStorage[b] = countyLocationMapping[countyStorage[b]];
                            }
                            if (portionsListing != "")
                            {
                                portionsListing += ", ";
                            }
                            portionsListing += $"{string.Join(", ", countyStorage)} and {lastOne} {stateMappingNames[stateMapping[stateThing]]}";
                        }
                        countyStorage.Clear();
                        countyStorage.Add(portionsHit5[i].Substring(2));
                        stateThing = portionsHit5[i].Substring(0, 2);
                    }
                }
                if (countyStorage.Count == 1)
                {
                    if (portionsListing != "")
                    {
                        portionsListing += ", and ";
                    }
                    portionsListing += $"{countyLocationMapping[countyStorage[0]]} {stateMappingNames[stateMapping[stateThing]]}";
                }
                else if (countyStorage.Count == 2)
                {
                    if (portionsListing != "")
                    {
                        portionsListing += ", and ";
                    }
                    portionsListing += $"{countyLocationMapping[countyStorage[0]]} and {countyLocationMapping[countyStorage[1]]} {stateMappingNames[stateMapping[stateThing]]}";
                }
                else
                {
                    string lastOne = countyLocationMapping[countyStorage[countyStorage.Count - 1]];
                    countyStorage.RemoveAt(countyStorage.Count - 1);
                    for (int b = 0; b < countyStorage.Count; b++)
                    {
                        countyStorage[b] = countyLocationMapping[countyStorage[b]];
                    }
                    if (portionsListing != "")
                    {
                        portionsListing += ", and ";
                    }
                    portionsListing += $"{string.Join(", ", countyStorage)} and {lastOne} {stateMappingNames[stateMapping[stateThing]]}";
                }
            }
            catch
            {

            }
            string followingCounties = "";
            if (rawCountyNameAffected.Count == 1)
            {
                followingCounties += $"{rawCountyNameAffected[0]}";
            }
            else if (rawCountyNameAffected.Count == 2)
            {
                followingCounties += $"{rawCountyNameAffected[0]} and {rawCountyNameAffected[1]}";
            }
            else
            {
                for (int i = 0; i < rawCountyNameAffected.Count; i++)
                {
                    if (i == (rawCountyNameAffected.Count - 1))
                    {
                        followingCounties += $"and {rawCountyNameAffected[i]}";
                    }
                    else
                    {
                        followingCounties += $"{rawCountyNameAffected[i]}, ";
                    }
                }
            }
            if (warningSelected == 2 || warningSelected == 5 || warningSelected == 7 || warningSelected == 9 || warningSelected == 11 || warningSelected == 26 || warningSelected == 27)
            {
                oldCounties = countiesAffectedUpdate.Split(new char[] { '-' }, StringSplitOptions.RemoveEmptyEntries).ToList();
                newCounties = countiesAffected.Split(new char[] { '-' }, StringSplitOptions.RemoveEmptyEntries).ToList();
