                        flagForNewCountyInContinuation = true;
                        externalCountiesContinuation += $"{countyData[s].countyName} {countyData[s].stateName} - ";
                    }
                }
                foreach (string s in oldCounties)
                {
                    if (newCounties.Contains(s))
                    {

                    }
                    else
                    {
                        rawCountyNameAffected2.Add($"{countyData[s].countyName}");
                        cancelledCounties.Add($"{s}");
