                        if (portionsHit4.Contains($"{s.Substring(0, 2)}{countyData[s].countyArea}"))
                        {

                        }
                        else
                        {
                            portionsHit4.Add($"{s.Substring(0, 2)}{countyData[s].countyArea}");
                        }
                        if (portionsHit2.Contains($"{s.Substring(0, 2)}{countyLocationMapping[countyData[s].countyArea]}"))
                        {

                        }
                        else
                        {
                            portionsHit2.Add($"{s.Substring(0, 2)}{countyLocationMapping[countyData[s].countyArea]}");
                        }
                    }
                }
