                            productText += $"In {stateMappingNames[stateMapping[area.Substring(0, 2)]]} this watch includes %(^#@*&%#^(*&" + Environment.NewLine + Environment.NewLine;
                        }
                    }
                    if (stateArea != area.Substring(2))
                    {
                        stateArea = area.Substring(2);
                        try
                        {
                            productText += $"In {countyLocationMapping[area.Substring(2)]} {stateMappingNames[stateMapping[area.Substring(0, 2)]]} " + Environment.NewLine + Environment.NewLine;
                        }
                        catch
                        {

                        }
                    }
                    currentLocationTrack = 0;
                    foreach (string fips in filteredFipsCodes)
                    {
                        try
                        {
                            if (area.Substring(0, 2) == fips.Substring(0, 2) && area.Substring(2) == countyData[fips].countyArea)
                            {
                                if (currentLocationTrack % 3 == 0)
                                {
                                    if (currentLocationTrack != 0)
                                    {
                                        productText += Environment.NewLine;
                                    }
                                }
                                currentProcessCounty = $"{countyData[fips].countyName}";
                                if (currentProcessCounty.Length >= 23)
                                {
                                    currentProcessCounty += new string(' ', 46 - currentProcessCounty.Length);
                                    currentLocationTrack += 2;
                                }
                                else
                                {
                                    currentProcessCounty += new string(' ', 23 - currentProcessCounty.Length);
                                    currentLocationTrack += 1;
                                }
                                productText += $"{currentProcessCounty}";
                                countCounties++;
                            }
                        }
                        catch
                        {

                        }
                    }
                    productText += Environment.NewLine + Environment.NewLine;
                }
                if (countCounties > 1)
                {
                    productText = productText.Replace("%(^#@*&%#^(*&", $"{countCounties} counties");
                }
                else
                {
                    productText = productText.Replace("%(^#@*&%#^(*&", $"{countCounties} county");
                }
                productText += $"LAT...LON {string.Join(" ", LatLonPoints)}" + Environment.NewLine + Environment.NewLine;
                productText += "$$";
                productText = productText.ToUpper();
            }
        }
