        public static void TextWorkstationCall(bool template, bool latlon, bool counties, bool cities, int countiesIncluded, bool partOfARelay, bool selfExpire, bool disableRounding, bool useMultiFormatting, string bulletinName, int indexOfIssuer, string productName, string productCategoryV)
        {
