            List<string> portionsHit2 = new List<string>();
            List<string> rawCountyNameAffected = new List<string>();
            List<string> rawCountyNameAffected2 = new List<string>();
            List<string> wfosAffected = new List<string>();
            List<string> statesInArea = new List<string>();
            lstImpactedCounties = new List<string>();
            List<string> filteredFipsCodes = new List<string>();
            List<string> portionsHit3 = new List<string>();
            List<string> portionsHit4 = new List<string>();
            if (countiesIncluded == 2 || countiesIncluded == 3)
            {
                countiesAffectedList.Clear();
                countiesAffectedList = countyData
                    .Where(x => x.Value.officeId == officeId)
                    .Select(x => x.Key)
                    .ToList();
            }
            foreach (string fips in countiesAffectedList)
            {
                if (countyData[fips].officeId == officeId)
                {
                    filteredFipsCodes.Add(fips);
                    lstImpactedCountiesStripped.Add($"{countyData[fips].countyName}");
                    if (countyData[fips].countyArea != "")
                    {
                        lstImpactedCounties.Add($"{countyData[fips].countyName} County in {countyLocationMapping[countyData[fips].countyArea]} {stateMappingNames[countyData[fips].stateName]}");
                    }
                    else
                    {
                        lstImpactedCounties.Add($"{countyData[fips].countyName} County in {stateMappingNames[countyData[fips].stateName]}");
                    }
                    rawCountyNameAffected.Add($"{countyData[fips].countyName}");
                    if (portionsHit.Contains($"{fips.Substring(0, 2)}{countyLocationMapping[countyData[fips].countyArea]}"))
                    {

                    }
                    else
                    {
                        portionsHit.Add($"{fips.Substring(0, 2)}{countyLocationMapping[countyData[fips].countyArea]}");
                    }
                    if (portionsHit3.Contains($"{fips.Substring(0, 2)}{countyData[fips].countyArea}"))
                    {

                    }
                    else
                    {
                        portionsHit3.Add($"{fips.Substring(0, 2)}{countyData[fips].countyArea}");
                    }
                    countiesAffected += $"{fips}-";
                }
                else
                {
                    flagForUnauthorizedCounty = true;
                    externalCounties += $"{countyData[fips].countyName} {countyData[fips].stateName} - ";
                }
            }
            portionsHit.Sort();
            portionsHit3.Sort();
            string currentStateProcess = "";
            string portionsListing = "";
            int segmentsWithCurrentState = 0;
            for (int i = 0; i < portionsHit.Count; i++)
            {
                if (currentStateProcess != portionsHit[i].Substring(0, 2))
                {
                    if (currentStateProcess != "")
                    {
                        if (segmentsWithCurrentState > 1)
                        {
                            portionsListing += $"and ";
                        }
                    }
                    if (portionsHit[i].Substring(2) != "")
                    {
                        portionsListing += $"{portionsHit[i].Substring(2)}";
                    }
                    if (currentStateProcess != "")
                    {
                        portionsListing += $" {stateMappingNames[stateMapping[currentStateProcess]]}, ";
                    }
                    else
                    {
                        if (portionsHit.Count != 1)
                        {
                            portionsListing += $", ";
                        }
                    }
                    segmentsWithCurrentState = 0;
                    currentStateProcess = portionsHit[i].Substring(0, 2);
                }
                else
                {
                    if (i == (portionsHit.Count - 1) && portionsHit.Count != 1)
                    {
                        portionsListing += $"and ";
                    }
                    if (portionsHit[i].Substring(2) != "")
                    {
                        portionsListing += $"{portionsHit[i].Substring(2)}";
                    }
                    if (i != (portionsHit.Count - 1))
                    {
                        portionsListing += $", ";
                    }
                }
                segmentsWithCurrentState += 1;
            }
            try
            {
                portionsListing += $" {stateMappingNames[stateMapping[currentStateProcess]]}";
            }
            catch
            {

            }
            string followingCounties = "";
