            {
                followingCounties += $"{rawCountyNameAffected[0]}";
            }
            else if (rawCountyNameAffected.Count == 2)
            {
                followingCounties += $"{rawCountyNameAffected[0]} and {rawCountyNameAffected[1]}";
            }
            else
            {
                for (int i = 0; i < rawCountyNameAffected.Count; i++)
                {
                    if (i == (rawCountyNameAffected.Count - 1))
                    {
                        followingCounties += $"and {rawCountyNameAffected[i]}";
                    }
                    else
                    {
                        followingCounties += $"{rawCountyNameAffected[i]}, ";
                    }
                }
            }
