                        {
                            if (portionsHit2.Count != 1)
                            {
                                portionsListing2 += $", ";
                            }
                        }
                        segmentsWithCurrentState = 0;
                        currentStateProcess = portionsHit2[i].Substring(0, 2);
                    }
                    else
                    {
                        if (i == (portionsHit2.Count - 1) && portionsHit2.Count != 1)
                        {
                            portionsListing2 += $"and ";
                        }
                        if (portionsHit2[i].Substring(2) != "")
                        {
                            portionsListing2 += $"{portionsHit2[i].Substring(2)}";
                        }
                        if (i != (portionsHit2.Count - 1))
                        {
                            portionsListing2 += $", ";
                        }
                    }
                    segmentsWithCurrentState += 1;
