                {
                    if (i == (rawCountyNameAffected2.Count - 1))
                    {
                        followingCounties2 += $"and {rawCountyNameAffected2[i]}";
                    }
                    else
                    {
                        followingCounties2 += $"{rawCountyNameAffected2[i]}, ";
                    }
                }
