            productText = string.Empty;
            productCategory = productCategoryV;
            productDesignator = officeId;
            productOriginator = indexOfIssuer;
            SAMETonage = false;
            Tonage1050 = false;
            Interrupt = false;
            Repeat = false;
            if (spcSelection == 3)
            {
                etn = nextVtecForContinuations;
            }
            else
            {
                etn = nextVtec;
            }
            broadcastCode = TTMapping[TTMapping.IndexOf(productCategory) + 4];
            if (broadcastCode[0] == Convert.ToChar("T"))
            {
                SAMETonage = true;
            }
            if (broadcastCode[1] == Convert.ToChar("T"))
            {
                Tonage1050 = true;
            }
            if (broadcastCode[2] == Convert.ToChar("I"))
            {
                Repeat = true;
            }
            if (broadcastCode[3] == Convert.ToChar("S"))
            {
                Interrupt = true;
            }
            DateTimeOffset now = DateTimeOffset.Now;
            DateTimeOffset nowReal = now;
            DateTimeOffset futureDateTime = now.AddMinutes(warngenDurationsList[durationSelected]);
            int remainder = futureDateTime.Minute % 15;
