                else if (timeZonesInAlert[0] == "M")
                {
                    now = now.AddHours(-2);
                    futureDateTime = futureDateTime.AddHours(-2);
                    futureRoundedTime = futureRoundedTime.AddHours(-2);
                    futureRoundedTime2 = futureRoundedTime2.AddHours(-2);
                    tz = "MDT";
                }
                else if (timeZonesInAlert[0] == "P")
