            int totalCumulativeMinutes = 0;
            totalCumulativeMinutes = 0;
            totalCumulativeMinutes += warngenDurationsList[durationSelected];
            totalCumulativeMinutes -= remainder;
            futureDateTime = now.AddMinutes(warngenDurationsList[durationSelected]);
            futureRoundedTime = futureDateTime.AddMinutes(-remainder);
            futureRoundedTime2 = futureDateTime.AddMinutes(-remainder);
            totalCumulativeMinutes = 0;
            totalCumulativeMinutes += warngenDurationsList[durationSelected];
