            string endTimeSegment = "";
            DateTimeOffset futureForTrackingPurposes = now.AddHours(24);
            if (futureRoundedTime.ToString("dd") == now.ToString("dd"))
            {
                if (Convert.ToInt32(futureRoundedTime2.ToString("HH")) >= 21)
                {
                    endTimeSegment = "TONIGHT";
                }
                else if (Convert.ToInt32(futureRoundedTime2.ToString("HH")) >= 18)
                {
                    endTimeSegment = "THIS EVENING";
                }
                else if (Convert.ToInt32(futureRoundedTime2.ToString("HH")) >= 12)
                {
                    endTimeSegment = "THIS AFTERNOON";
                }
                else
                {
                    endTimeSegment = "THIS MORNING";
                }
            }
            else if (futureRoundedTime.ToString("dd") == futureForTrackingPurposes.ToString("dd"))
            {
