                {
                    endTimeSegment = "TOMORROW NIGHT";
                }
                else if (Convert.ToInt32(futureRoundedTime2.ToString("HH")) >= 18)
                {
                    endTimeSegment = "TOMORROW EVENING";
                }
                else if (Convert.ToInt32(futureRoundedTime2.ToString("HH")) >= 12)
                {
                    endTimeSegment = "TOMORROW AFTERNOON";
                }
                else
                {
                    endTimeSegment = "TOMORROW MORNING";
                }
            }
            else
            {
                if (Convert.ToInt32(futureRoundedTime2.ToString("HH")) >= 21)
                {
                    endTimeSegment = $"{futureRoundedTime2.ToString("dddd").ToUpper()} NIGHT";
                }
                else if (Convert.ToInt32(futureRoundedTime2.ToString("HH")) >= 18)
                {
                    endTimeSegment = $"{futureRoundedTime2.ToString("dddd").ToUpper()} EVENING";
                }
                else if (Convert.ToInt32(futureRoundedTime2.ToString("HH")) >= 12)
                {
