            futureRoundedUtc2 = futureUtc.AddMinutes(-remainder);
            futureUtc = currentUtc.AddMinutes(10);
            DateTime futureCancelledUtc = futureUtc;
            string startUtc = currentUtc.ToString("HHmm");
