            string endUtcCancelledFips = futureCancelledUtc.ToString("ddHHmm");
            vtecDateStart = currentUtc.ToString("yyMMdd\\THHmm\\Z");
            vtecDateEnd = futureRoundedUtc2.ToString("yyMMdd\\THHmm\\Z");

            DateTimeOffset endOffset = new DateTimeOffset(futureRoundedUtc, TimeSpan.Zero);
            if (selfExpire)
            {
                endUnixTimestamp = 0;
