            string mostProbableWind = "";
            string mostProbableTornado = "";
            int etnInteger = Convert.ToInt32(etn);
            dateTimeStamp = $"{currentTime}";
            List<string> fipsCancelledList = new List<string>();

            if (countiesAffected.Contains("-"))
            {
                fipsList = countiesAffected.Split('-').ToList();
                fipsList.Remove("");
