            }

            if (cancelledCountiesView2.Contains("-"))
            {
                fipsCancelledList = cancelledCountiesView2.Split('-').ToList();
                fipsCancelledList.Remove("");
                fipsCancelledList.Sort();
            }

            foreach (var item in fipsCancelledList)
            {
                if (item.Substring(0, 2) != lastState)
                {
                    if (stateMapping.TryGetValue(item.Substring(0, 2), out string code))
                        countyCancelledFips += $"{code}C";
                    countyCancelledFipsZones += $"{code}Z";
                    lastState = item.Substring(0, 2);
                }
                countyCancelledFips += $"{item.Substring(2)}-";
                countyCancelledFipsZones += $"{item.Substring(2)}-";
                cancelledFipsCountyNames += $"{countyLookupFips[countyLookupFips.IndexOf(item) + 1]} {countyLookupFips[countyLookupFips.IndexOf(item) + 2]}-";
            }

            lastState = "";

            foreach (var item in fipsList)
            {
                if (item.Substring(0, 2) != lastState)
                {
                    if (stateMapping.TryGetValue(item.Substring(0, 2), out string code))
                        countyFips += $"{code}C";
                    countyFipsZones += $"{code}Z";
                    lastState = item.Substring(0, 2);
                }
                countyFips += $"{item.Substring(2)}-";
                countyFipsZones += $"{item.Substring(2)}-";
                fipsCountiesNames += $"{countyLookupFips[countyLookupFips.IndexOf(item) + 1]} {countyLookupFips[countyLookupFips.IndexOf(item) + 2]}-";
